{
  "response_type": "jwrs_execution_result",
  "jwrs_projection": {
    "response_type": "jwrs_projection",
    "request": {
      "task": "Construct and execute a specification for communicating a prompt to Gemini using the supplied MetaProcedure, JavaScript source archive, and Agents.md JSON projection as authoritative evidence.",
      "output_artifacts": [
        "specification",
        "gemini-prompt-communicator.js",
        "gemini-prompt-workflow.yaml",
        "gemini-prompt-message-config.json"
      ]
    },
    "return_schema": {
      "type": "object",
      "required": [
        "response_type",
        "jwrs_projection",
        "projection_printed_before_execution",
        "specification",
        "gemini-prompt-communicator.js",
        "gemini-prompt-workflow.yaml",
        "gemini-prompt-message-config.json",
        "same_turn_execution",
        "status"
      ],
      "properties": {
        "response_type": { "type": "string", "enum": ["jwrs_execution_result"] },
        "jwrs_projection": { "type": "object" },
        "projection_printed_before_execution": { "type": "boolean" },
        "specification": {
          "type": "object",
          "required": [
            "purpose",
            "authorities",
            "procedure",
            "configuration_categories",
            "invariants",
